  kechikayotgan_topshiriqlar:DashboardItem[]
  muhim_murojaatlar:DashboardItem[]
  statistika:{jami_hujjatlar:number;faol_nhh:number;jami_topshiriqlar:number;bajarilgan_topshiriqlar:number;kechikkan_topshiriqlar:number}
